import { randomUUID } from "node:crypto";
import { Pool } from "pg";
import AxeBuilder from "@axe-core/playwright";
import {
  test,
  expect,
  setThemePlan,
  setThemeQuotaGating,
} from "../helpers/theme-browser";

const pool = new Pool({ connectionString: process.env.DATABASE_URL });
const colors = [
  "Cyan",
  "Teal",
  "Emerald",
  "Lime",
  "Amber",
  "Orange",
  "Rose",
  "Pink",
  "Violet",
  "Blue",
];
test.afterAll(() => pool.end());

test("preview highlight: all colors, themes, surfaces, keyboard, persistence and accessibility", async ({
  page,
  themeUser,
}, testInfo) => {
  test.setTimeout(180000);
  page.setDefaultTimeout(15000);
  await page.emulateMedia({ reducedMotion: "reduce" });
  const contact = randomUUID();
  const template = randomUUID();
  await pool.query(
    "INSERT INTO \"Contact\" (id,\"userId\",name,email,company,\"jobRole\") VALUES ($1,$2,'Alex Smith','[REDACTED_EMAIL]','Acme','Engineer')",
    [contact, themeUser],
  );
  await pool.query(
    "INSERT INTO \"Template\" (id,\"userId\",name,subject,body) VALUES ($1,$2,'Highlight test','{{name}} {{company}} {{role}}','{{name}} {{company}} {{role}}')",
    [template, themeUser],
  );
  await page.goto("/templates?new=1");
  await page
    .getByLabel("Subject", { exact: true })
    .fill("{{name}} {{company}} {{role}}");
  await page
    .getByLabel("Message", { exact: true })
    .fill("{{name}} {{company}} {{role}} {{invalid}}");
  if (testInfo.project.name === "mobile")
    await page.getByRole("tab", { name: "Preview", exact: true }).click();
  const trigger = page.getByRole("button", {
    name: "Highlight color",
    exact: true,
  });
  const menu = page.getByRole("menu", { name: "Highlight color", exact: true });
  const preview = page.locator(".mail-preview");
  await expect(preview).toHaveAttribute("data-preview-highlight", "cyan");
  for (const surface of ["template", "compose"]) {
    if (surface === "compose") {
      page.once("dialog", (dialog) => dialog.accept());
      await page
        .getByRole("link", { name: "Compose", exact: true })
        .first()
        .click();
      await page
        .getByLabel("Choose a template", { exact: true })
        .selectOption(template);
      await page.getByRole("checkbox", { name: /Alex Smith/ }).check();
      await expect(preview).toHaveAttribute("data-preview-highlight", "blue");
    }
    for (const theme of [
      "Lavender Light",
      "Nightbloom Dark",
      "Chalk Light",
      "Obsidian Dark",
    ]) {
      await page.getByRole("button", { name: "Choose appearance" }).click();
      await page
        .getByRole("menuitemradio", { name: theme, exact: true })
        .click();
      const backgrounds = new Set<string>();
      for (const name of colors) {
        await trigger.click();
        await expect(menu.getByRole("menuitemradio")).toHaveCount(10);
        await page.getByRole("menuitemradio", { name, exact: true }).click();
        await expect(trigger).toBeFocused();
        await expect(menu).toHaveCount(0);
        await expect(preview).toHaveAttribute(
          "data-preview-highlight",
          name.toLowerCase(),
        );
        await expect(preview.locator("mark:not(.invalid)")).toHaveText([
          "Alex Smith",
          "Acme",
          "Engineer",
          "Alex Smith",
          "Acme",
          "Engineer",
        ]);
        const background = await preview
          .locator("mark:not(.invalid)")
          .first()
          .evaluate((mark) => getComputedStyle(mark).backgroundColor);
        backgrounds.add(background);
        if (surface === "template") {
          const invalid = await preview
            .locator("mark.invalid")
            .evaluate((mark) => getComputedStyle(mark).backgroundColor);
          expect(invalid).not.toBe(background);
        }
        const contrast = await preview
          .locator("mark:not(.invalid)")
          .evaluateAll((marks) => {
            function luminance(rgb: string) {
              const channels = rgb
                .match(/[\d.]+/g)!
                .slice(0, 3)
                .map(Number)
                .map((v) => {
                  const s = v / 255;
                  return s <= 0.04045
                    ? s / 12.92
                    : ((s + 0.055) / 1.055) ** 2.4;
                });
              return (
                channels[0] * 0.2126 +
                channels[1] * 0.7152 +
                channels[2] * 0.0722
              );
            }
            return marks.map((mark) => {
              const style = getComputedStyle(mark);
              const a = luminance(style.color),
                b = luminance(style.backgroundColor);
              return (Math.max(a, b) + 0.05) / (Math.min(a, b) + 0.05);
            });
          });
        for (const ratio of contrast) expect(ratio).toBeGreaterThanOrEqual(4.5);
      }
      expect(backgrounds.size).toBe(10);
      await trigger.click();
      const blue = page.getByRole("menuitemradio", {
        name: "Blue",
        exact: true,
      });
      await expect(blue).toBeFocused();
      await expect(blue).toHaveAttribute("aria-checked", "true");
      const selectedBackground = await preview
        .locator("mark:not(.invalid)")
        .first()
        .evaluate((mark) => getComputedStyle(mark).backgroundColor);
      await expect(blue).toHaveCSS("background-color", selectedBackground);
      const bounds = (await menu.boundingBox())!;
      expect(bounds.x).toBeGreaterThanOrEqual(0);
      expect(bounds.x + bounds.width).toBeLessThanOrEqual(
        page.viewportSize()!.width,
      );
      const items = await menu.getByRole("menuitemradio").all();
      const first = (await items[0].boundingBox())!;
      const fifth = (await items[4].boundingBox())!;
      const sixth = (await items[5].boundingBox())!;
      expect(Math.abs(first.y - fifth.y)).toBeLessThan(1);
      expect(sixth.y).toBeGreaterThan(first.y);
      expect(
        (
          await new AxeBuilder({ page })
            .include(".preview-highlight-picker")
            .include(".mail-preview")
            .analyze()
        ).violations,
      ).toEqual([]);
      await page.screenshot({
        path: testInfo.outputPath(
          `${surface}-${theme.replaceAll(" ", "-")}.png`,
        ),
      });
      await page.keyboard.press("Escape");
      await expect(trigger).toBeFocused();
    }
  }
  await page.reload();
  await expect(trigger).toHaveAttribute("title", "Highlight color: blue");
  await trigger.focus();
  await page.keyboard.press("ArrowDown");
  await page.keyboard.press("Home");
  await expect(
    page.getByRole("menuitemradio", { name: "Cyan", exact: true }),
  ).toBeFocused();
  await page.keyboard.press("ArrowDown");
  await expect(
    page.getByRole("menuitemradio", { name: "Orange", exact: true }),
  ).toBeFocused();
  await page.keyboard.press("ArrowRight");
  await page.keyboard.press("ArrowUp");
  await expect(
    page.getByRole("menuitemradio", { name: "Teal", exact: true }),
  ).toBeFocused();
  await page.keyboard.press(" ");
  await expect(trigger).toBeFocused();
  await expect(trigger).toHaveAttribute("title", "Highlight color: teal");
  await trigger.click();
  await page.mouse.click(1, 1);
  await expect(menu).toHaveCount(0);
});

for (const storage of ["invalid", "blocked"] as const) {
  test(`preview highlight: ${storage} storage fallback`, async ({ page }) => {
    await page.addInitScript((storage) => {
      if (storage === "invalid")
        localStorage.setItem("mailloop-preview-highlight", "invalid");
      else {
        Storage.prototype.getItem = () => {
          throw new Error("Blocked");
        };
        Storage.prototype.setItem = () => {
          throw new Error("Blocked");
        };
      }
    }, storage);
    await page.goto("/templates?new=1");
    if (test.info().project.name === "mobile")
      await page.getByRole("tab", { name: "Preview", exact: true }).click();
    const trigger = page.getByRole("button", {
      name: "Highlight color",
      exact: true,
    });
    await expect(trigger).toHaveAttribute("title", "Highlight color: cyan");
    await trigger.click();
    await page
      .getByRole("menuitemradio", { name: "Rose", exact: true })
      .click();
    await expect(page.locator(".mail-preview")).toHaveAttribute(
      "data-preview-highlight",
      "rose",
    );
    await page
      .getByRole("link", { name: "Compose", exact: true })
      .first()
      .click();
    await expect(trigger).toHaveAttribute("title", "Highlight color: rose");
    if (storage === "blocked") {
      await page.reload();
      await page.goto("/templates?new=1");
      if (test.info().project.name === "mobile")
        await page.getByRole("tab", { name: "Preview", exact: true }).click();
      await expect(trigger).toHaveAttribute("title", "Highlight color: cyan");
    }
  });
}

for (const gated of [true, false]) {
  test(`preview highlight: Free palette and live lifecycle with quota gating ${gated}`, async ({
    page,
    themeUser,
  }, info) => {
    test.setTimeout(120000);
    await setThemeQuotaGating(gated);
    const contact = randomUUID();
    const template = randomUUID();
    await pool.query(
      `INSERT INTO "Contact" (id,"userId",name,email,company,"jobRole") VALUES ($1,$2,'Alex Smith','[REDACTED_EMAIL]','Acme','Engineer')`,
      [contact, themeUser],
    );
    await pool.query(
      `INSERT INTO "Template" (id,"userId",name,subject,body) VALUES ($1,$2,'Highlight lifecycle','{{name}}','{{company}} {{role}}')`,
      [template, themeUser],
    );
    try {
      await page.addInitScript(() =>
        localStorage.setItem("mailloop-preview-highlight", "violet"),
      );
      await setThemePlan(themeUser, "FREE");
      await page.goto(`/templates?edit=${template}`);
      if (info.project.name === "mobile") {
        await page.getByRole("tab", { name: "Preview", exact: true }).click();
      }
      const preview = page.locator(".mail-preview");
      const lock = page.getByRole("menuitemradio", {
        name: "Blue — Premium required",
        exact: true,
      });
      const menu = page.getByRole("menu", { name: "Highlight color" });
      const picker = page.getByRole("button", {
        name: "Highlight color",
        exact: true,
      });
      const popup = page.getByRole("tooltip");
      const refresh = () =>
        page.evaluate(() =>
          window.dispatchEvent(new Event("mailloop:access-refresh")),
        );
      for (const surface of ["template", "compose"]) {
        if (surface === "compose") {
          await page.goto("/compose");
          await page.getByRole("checkbox", { name: /Alex Smith/ }).check();
          await expect(
            page.getByLabel("Preview recipient", { exact: true }),
          ).toHaveValue(contact);
          await page
            .getByLabel("Choose a template", { exact: true })
            .selectOption(template);
          await expect(
            page.getByLabel("Choose a template", { exact: true }),
          ).toHaveValue(template);
        }
        await expect(preview).toHaveAttribute("data-preview-highlight", "cyan");
        await expect(picker).toBeVisible();
        await expect(picker).toHaveAttribute("title", "Highlight color: cyan");
        await picker.click();
        await expect(menu.getByRole("menuitemradio")).toHaveCount(10);
        await expect(
          menu.getByRole("menuitemradio", { name: /Premium required/ }),
        ).toHaveCount(9);
        await expect(
          menu.getByRole("menuitemradio", { name: "Cyan", exact: true }),
        ).toHaveAttribute("aria-checked", "true");
        await expect(lock).toBeEnabled();
        await page.mouse.move(0, 0);
        await lock.focus();
        await expect(lock).toHaveAttribute("aria-describedby", /.+/);
        const focusedPopup = page.locator(
          `[role="tooltip"]#${await lock.getAttribute("aria-describedby")}`,
        );
        await expect(focusedPopup).toContainText("Free includes Cyan.");
        await page.keyboard.press("Tab");
        const upgrade = focusedPopup.getByRole("link", {
          name: "Upgrade to Premium",
        });
        await expect(upgrade).toBeFocused();
        await expect(upgrade).toHaveAttribute("href", "/usage");
        await page.keyboard.press("Escape");
        await expect(focusedPopup).toHaveCount(0);
        await expect(lock).toBeFocused();
        await expect(menu).toBeVisible();
        await page.mouse.click(1, 1);
        await expect(menu).toHaveCount(0);
        await picker.click();
        await lock.focus();
        await expect(popup).toBeVisible();
        await lock.click();
        const upgradeDialog = page.getByRole("dialog", {
          name: "Upgrade to Premium",
          exact: true,
        });
        await expect(upgradeDialog).toBeVisible();
        await expect(upgradeDialog).toContainText(
          "Custom preview highlight colors are a Premium feature",
        );
        await page.keyboard.press("Escape");
        await expect(picker).toBeFocused();
        await picker.click();
        await lock.focus();
        await expect(popup).toBeVisible();
        await expect(preview).toHaveAttribute("data-preview-highlight", "cyan");
        expect(
          await page.evaluate(() =>
            localStorage.getItem("mailloop-preview-highlight"),
          ),
        ).toBe("violet");
        await popup.hover();
        await expect(popup).toBeVisible();
        const bounds = (await popup.boundingBox())!;
        expect(bounds.x).toBeGreaterThanOrEqual(0);
        expect(bounds.x + bounds.width).toBeLessThanOrEqual(
          page.viewportSize()!.width,
        );
        expect(bounds.y).toBeGreaterThanOrEqual(0);
        expect(bounds.y + bounds.height).toBeLessThanOrEqual(
          page.viewportSize()!.height,
        );
        expect(
          (
            await new AxeBuilder({ page })
              .include(".preview-highlight-picker")
              .include('[role="tooltip"]')
              .analyze()
          ).violations,
        ).toEqual([]);
        await page.mouse.click(1, 1);
        await expect(popup).toHaveCount(0);
        await setThemePlan(themeUser, "PAID");
        await refresh();
        await expect(picker).toBeVisible();
        await expect(preview).toHaveAttribute(
          "data-preview-highlight",
          "violet",
        );
        await picker.click();
        await expect(
          page.getByRole("menu", { name: "Highlight color" }),
        ).toBeVisible();
        await setThemePlan(themeUser, "FREE");
        await refresh();
        await expect(picker).toHaveAttribute("title", "Highlight color: cyan");
        await expect(menu).toHaveCount(0);
        await expect(preview).toHaveAttribute("data-preview-highlight", "cyan");
        expect(
          await page.evaluate(() =>
            localStorage.getItem("mailloop-preview-highlight"),
          ),
        ).toBe("violet");
      }
      await setThemePlan(themeUser, "PAID", new Date(Date.now() + 6000));
      await refresh();
      await expect(picker).toBeVisible();
      await picker.click();
      await expect(picker).toHaveAttribute("title", "Highlight color: cyan", {
        timeout: 20000,
      });
      await expect(preview).toHaveAttribute("data-preview-highlight", "cyan");
      await expect(
        page.getByRole("menu", { name: "Highlight color" }),
      ).toHaveCount(0);
      await setThemePlan(themeUser, "PAID");
      await refresh();
      await expect(preview).toHaveAttribute("data-preview-highlight", "violet");
      await setThemePlan(themeUser, "FREE");
      await refresh();
      await expect(picker).toHaveAttribute("title", "Highlight color: cyan");
      await picker.click();
      const cyan = menu.getByRole("menuitemradio", {
        name: "Cyan",
        exact: true,
      });
      await cyan.click();
      expect(
        await page.evaluate(() =>
          localStorage.getItem("mailloop-preview-highlight"),
        ),
      ).toBe("violet");
      await picker.click();
      await page.keyboard.press("ArrowRight");
      await expect(
        menu.getByRole("menuitemradio", {
          name: "Teal — Premium required",
          exact: true,
        }),
      ).toBeFocused();
      await expect(popup).toBeVisible();
      await page.keyboard.press("Escape");
      await expect(popup).toHaveCount(0);
      await page.keyboard.press("Escape");
      await expect(menu).toHaveCount(0);
      await expect(picker).toBeFocused();
      await picker.click();
      await lock.focus();
      page.once("dialog", (dialog) => dialog.accept());
      await popup.getByRole("link", { name: "Upgrade to Premium" }).click();
      await expect(page).toHaveURL(/\/usage$/);
    } finally {
      await setThemeQuotaGating(false);
    }
  });
}
